        var nativeHolder=mc().getSingleplayerServer().getRecipeManager().byKey(ResourceLocation.parse(ID)).orElseThrow();var ops=mc().getSingleplayerServer().registryAccess().createSerializationContext(com.mojang.serialization.JsonOps.INSTANCE);var copy=GenericCompatFixture.GenericRecipe.CODEC.codec().parse(ops,dev.kubejseditor.export.GenericFormatter.encodeRecipe(nativeHolder)).getOrThrow();var fake=new RecipeHolder<>(ResourceLocation.parse("display:unregistered"),copy);var wrapped=new PatchVerificationJei.Frame(Optional.of(new PatchVerificationJei.Box(fake)));
