        click("更多");choose("通用字段补丁");check(mc().screen instanceof FieldPatchScreen,"Unmapped data opens the independent raw patch page");var patch=(FieldPatchScreen)mc().screen;var search=patch.children().stream().filter(c->c instanceof EditBox).map(c->(EditBox)c).findFirst().orElseThrow();search.setValue("/feedstock/ingredient/item");var typed=WorkspaceJeiPlugin.runtime.getIngredientManager().createTypedIngredient(new ItemStack(Items.COPPER_INGOT)).orElseThrow();var targets=WorkspaceJeiPlugin.patchGhostHandler().getTargetsTyped(patch,typed,true);check(targets.size()==1,"The JEI patch handler exposes the exact raw item-ID path");targets.getFirst().accept(typed.getIngredient());patch.append(JsonPatches.operation("replace","/settings/work",new JsonPrimitive(91)));patch.append(JsonPatches.operation("replace","/product/components/minecraft:custom_data/origin",new JsonPrimitive("patched")));click("检查并保存补丁");check(mc().screen instanceof CompatibilityScreen,"Valid raw patch saves through the existing draft pipeline");screen=(CompatibilityScreen)mc().screen;check(JsonPatches.read(screen.draft.data,"/feedstock/count").getAsInt()==20480,"Raw item replacement retains large quantities");check(JsonPatches.read(screen.draft.data,"/feedstock/ingredient/item").getAsString().equals("minecraft:copper_ingot"),"JEI drop changes the native ID rather than only its displayed icon");check(JsonPatches.read(ProjectStore.read(root()).recipes.get(ID).data,"/settings/work").getAsInt()==91,"Raw patch results survive disk serialization");
        for(int scale:List.of(2,3)){mc().options.guiScale().set(scale);mc().resizeDisplay();((CompatibilityScreen)mc().screen).openFieldPatches();for(var child:mc().screen.children())if(child instanceof Button b)check(b.getX()>=0&&b.getX()+b.getWidth()<=mc().screen.width&&b.getY()>=0&&b.getY()+b.getHeight()<=mc().screen.height,"Raw patch controls remain within GUI scale "+scale);click("取消");}
        screen=(CompatibilityScreen)mc().screen;var saved=screen.draft.data.deepCopy();screen.openFieldPatches();patch=(FieldPatchScreen)mc().screen;patch.append(JsonPatches.operation("replace","/settings/work",new JsonPrimitive(-1)));click("检查并保存补丁");check(mc().screen instanceof FieldPatchScreen&&EditorRuntime.project().recipes.get(ID).data.equals(saved),"Native codec failure keeps both the previous saved draft and editable patch preview");click("取消");screen=(CompatibilityScreen)mc().screen;screen.openFieldPatches();patch=(FieldPatchScreen)mc().screen;patch.append(JsonPatches.operation("add","/ignored_field",new JsonPrimitive(99)));click("检查并保存补丁");check(mc().screen instanceof FieldPatchScreen,"A patch entirely ignored by the native codec cannot claim success");click("取消");
